/* Architecture editorial: public concepts, not internal topology. */
const A_VERTICALS=[{"name": "Banking", "slug": "banking", "title": "Uma conta. Várias formas de operar.", "copy": "Aplicativo, desktop e console apresentam saldo, extrato e operações a públicos diferentes. Identidade, permissões e capacidades bancárias sustentam os canais sem replicar a regra em cada tela.", "shared": ["Identidade", "BaaS", "Portfólio", "Permissões", "Eventos"], "specific": "Marca e canais · papéis de operação · regras de autorização", "steps": ["Identificar", "Consultar", "Autorizar", "Operar"]}, {"name": "Crédito", "slug": "credit", "title": "Do pedido à vida da operação.", "copy": "Produto, cálculo, política e formalização se conectam em uma esteira. A mesa acompanha o dossiê, as condições de liberação e a carteira; cada modalidade acrescenta suas particularidades.", "shared": ["Portfólio", "Cálculo", "Pricing", "Decisão", "Documentos"], "specific": "Modalidade e lastro · condições comerciais · alçadas da mesa", "steps": ["Simular", "Analisar", "Formalizar", "Acompanhar"]}, {"name": "Decisão", "slug": "decision", "title": "Muda a política. A jornada continua.", "copy": "A esteira reúne as fontes configuradas. O motor aplica a versão publicada da política e devolve resultado e motivo. O mesmo fundamento pode participar de elegibilidade, limites ou encaminhamento para análise.", "shared": ["Dados", "Fontes", "Regras", "Identidade", "Evidências"], "specific": "Dados de entrada · política versionada · tratamento de exceções", "steps": ["Receber", "Consultar", "Avaliar", "Encaminhar"]}, {"name": "Recebíveis", "slug": "credit", "title": "Uma base de crédito. Outro lastro.", "copy": "Em uma composição possível, recebíveis elegíveis entram no dossiê, o cálculo organiza a oferta e a formalização prepara a operação. Conciliação, registro e liquidação dependem dos parceiros conectados.", "shared": ["Dados", "Cálculo", "Pricing", "Decisão", "Assinatura"], "specific": "Elegibilidade dos títulos · concentração · registro e conciliação", "steps": ["Conferir", "Precificar", "Formalizar", "Conciliar"], "note": "Composição ilustrativa · integrações a validar"}, {"name": "Copiloto", "url": "/agentes/", "title": "Conhecimento que acompanha o trabalho.", "copy": "Em uma visita técnica, vídeo e documentos podem dar contexto ao especialista. A IA prepara um resumo e sugere consultas ao manual; o técnico valida o diagnóstico e autoriza as próximas ações.", "shared": ["Vídeo", "IA", "Documentos", "Dados", "Workflow"], "specific": "Manuais autorizados · contexto do equipamento · validação técnica", "steps": ["Contextualizar", "Consultar", "Revisar", "Registrar"], "note": "Aplicação possível · depende da base técnica e das integrações"}, {"name": "Atendimento", "url": "/workflows/", "title": "A conversa avança para uma ação.", "copy": "Uma central de serviços pode reconhecer a solicitação, consultar o andamento no sistema de origem e organizar um agendamento. Quando falta contexto ou autorização, a jornada encaminha o caso à equipe.", "shared": ["Conversa", "Identidade", "Agenda", "Dados", "Workflow"], "specific": "Política de atendimento · sistemas conectados · encaminhamento humano", "steps": ["Entender", "Consultar", "Agendar", "Acompanhar"], "note": "Aplicação possível · escopo definido por operação"}];
function aAssemblyLayers(){
const cube=(x,y,w,h,accent=false)=>{const top=accent?'url(#ah-orange)':'url(#ah-top)',left=accent?'#d67435':'url(#ah-left)',right=accent?'#ab5026':'url(#ah-right)';return `<g stroke="#f6f3ee" stroke-opacity=".13" stroke-width=".7" stroke-linejoin="round"><path d="M${x} ${y}l${w} ${-w/2} ${w} ${w/2} ${-w} ${w/2}Z" fill="${top}"/><path d="M${x} ${y}l${w} ${w/2}v${h}l${-w} ${-w/2}Z" fill="${left}"/><path d="M${x+w} ${y+w/2}l${w} ${-w/2}v${h}l${-w} ${w/2}Z" fill="${right}"/></g>`};
let out='';for(let layer=0;layer<4;layer++){let cells='';const y=460-layer*102;for(let depth=0;depth<9;depth++)for(let i=0;i<5;i++){const j=depth-i;if(j<0||j>4)continue;let x=340+(i-j)*38,cy=y+(i+j)*19;const loose=layer===3&&i>2&&j<2;const shift=loose?(i-2)*25:0;cells+=cube(x+shift,cy-(loose?24+(i-j)*8:0),36,layer===0?23:35,layer===1||(loose&&i===4));}out+=`<g class="a-stratum a-stratum-${layer}" style="--a-lift:${layer*-4}px">${cells}</g>`}out+=`<g class="a-loose">${cube(605,146,26,29,true)}${cube(545,80,21,25)}${cube(635,251,18,21)}</g>`;return out;
}
function aSvg(kind){
if(kind==='hero')return `<svg class="a-assembly" viewBox="0 0 760 700" role="img" aria-label="Escultura modular em camadas: pequenas peças se reúnem em uma arquitetura compartilhada"><defs><linearGradient id="ah-top" x2="1" y2="1"><stop stop-color="#b99bce"/><stop offset="1" stop-color="#8e68ae"/></linearGradient><linearGradient id="ah-left" x2="1" y2="1"><stop stop-color="#795393"/><stop offset="1" stop-color="#59346f"/></linearGradient><linearGradient id="ah-right" x2="1" y2="1"><stop stop-color="#553467"/><stop offset="1" stop-color="#392047"/></linearGradient><linearGradient id="ah-orange" x2="1" y2="1"><stop stop-color="#ffc56b"/><stop offset="1" stop-color="#f18a43"/></linearGradient><radialGradient id="ah-shadow"><stop stop-color="#3b214a" stop-opacity=".24"/><stop offset="1" stop-color="#3b214a" stop-opacity="0"/></radialGradient><filter id="ah-material"><feTurbulence type="fractalNoise" baseFrequency=".65" numOctaves="2" stitchTiles="stitch" result="noise"/><feColorMatrix in="noise" type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".035"/></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply"/></filter></defs><ellipse cx="375" cy="594" rx="290" ry="83" fill="url(#ah-shadow)"/><g stroke="#b5a2bf" fill="none" opacity=".45"><path d="M90 565l270 137 315-159M360 702V630"/><path stroke-dasharray="3 7" d="M175 225v330M565 225v330M370 110v450"/></g>${aAssemblyLayers()}<g fill="none" stroke="#9676ac" stroke-width="1"><path d="M194 170H94v-35M548 326h98v-28M540 475h106v34"/><circle cx="194" cy="170" r="3" fill="#734b9c"/><circle cx="548" cy="326" r="3" fill="#734b9c"/><circle cx="540" cy="475" r="3" fill="#e58a43"/></g><g font-family="Inter,sans-serif" font-size="10" letter-spacing="1.5" fill="#67556f"><text x="45" y="119">COMPOSIÇÕES</text><text x="568" y="283">CAPACIDADES</text><text x="584" y="532">BASE COMUM</text></g></svg>`;
if(kind==='reuse')return `<svg viewBox="0 0 620 320" role="img" aria-label="Identidade compartilhada participa de banking, crédito e decisão"><g fill="none" stroke="#a18bad" stroke-width="2"><path d="M110 160H235Q270 160 270 65H465M235 160H465M235 160Q270 160 270 255H465"/><path class="a-stream" d="M110 160H235Q270 160 270 65H465M235 160H465M235 160Q270 160 270 255H465" stroke="#734b9c" stroke-width="4"/></g><rect x="30" y="110" width="100" height="100" fill="#734b9c"/><circle cx="80" cy="160" r="24" fill="none" stroke="#f6f3ee" stroke-width="12"/><g fill="#f48743"><circle cx="465" cy="65" r="24"/><path d="M440 135h50v50h-50z"/><path d="M465 225l30 55h-60z"/></g><g fill="#171717" font-size="13"><text x="505" y="70">Banking</text><text x="505" y="165">Crédito</text><text x="505" y="260">Decisão</text><text x="30" y="245">IDENTIDADE</text></g></svg>`;
return `<svg viewBox="0 0 620 300" role="img" aria-label="Um provedor pode mudar atrás de uma fronteira de integração estável"><path d="M75 150H540" stroke="#a391b5" stroke-width="2"/><rect x="25" y="105" width="120" height="90" fill="#e3d6ef"/><text x="85" y="157" text-anchor="middle" font-size="15">Produto</text><rect x="230" y="65" width="140" height="170" fill="#734b9c"/><text x="300" y="146" text-anchor="middle" fill="white" font-size="14">Contrato</text><text x="300" y="168" text-anchor="middle" fill="white" font-size="14">da capacidade</text><g class="a-provider"><circle cx="510" cy="150" r="55" fill="#f48743"/><path d="M485 150h50m-25-25v50" stroke="#3c224c" stroke-width="4"/></g><path class="a-stream" d="M145 150H230M370 150H455" stroke="#734b9c" stroke-width="4"/><text x="510" y="248" text-anchor="middle" font-size="13">Integração externa</text></svg>`;
}
function aCompositionMap(i){
const d=A_VERTICALS[i];const points=[[90,70],[280,52],[470,70],[170,170],[390,170]];
return `<svg class="a-composition-map" viewBox="0 0 560 420" role="img" aria-label="${ce(d.name)}: ${ce(d.shared.join(', '))} conectados em uma jornada"><defs><linearGradient id="am-bg" x2="0" y2="1"><stop stop-color="#463051"/><stop offset="1" stop-color="#2d2037"/></linearGradient></defs><rect width="560" height="420" rx="4" fill="url(#am-bg)"/><g stroke="#e1d4ed" stroke-opacity=".06">${Array.from({length:15},(_,n)=>`<path d="M${n*40} 0v420M0 ${n*40}h560"/>`).join('')}</g><g fill="none" stroke="#bfa4cf" stroke-opacity=".5" stroke-width="1.5">${points.map(([x,y])=>`<path d="M${x} ${y+36}V230Q${x} 250 280 250"/>`).join('')}</g><g fill="none" stroke="#f9bf6b" stroke-width="2" class="a-map-flow">${points.map(([x,y])=>`<path d="M${x} ${y+36}V230Q${x} 250 280 250"/>`).join('')}</g>${points.map(([x,y],j)=>`<g class="a-map-node" style="--node-delay:${j*.12}s"><rect x="${x-71}" y="${y-31}" width="142" height="66" rx="3" fill="${j===i%5?'#f1a15e':'#e7dced'}"/><g transform="translate(${x-53} ${y-13})" stroke="${j===i%5?'#693a29':'#745186'}" fill="none" stroke-width="1.6">${['<circle cx="10" cy="7" r="6"/><path d="M0 26c0-13 20-13 20 0"/>','<path d="M0 2h21v22H0zM0 10h21M8 10v14"/>','<path d="M10 0l12 13-12 13L-2 13zM-2 13h24"/>','<circle cx="10" cy="13" r="11"/><path d="M10 2v22M-1 13h22"/>','<path d="M1 0h14l6 6v21H1zM5 13h12M5 19h9"/>'][j]}</g><text x="${x-20}" y="${y+5}" fill="#3d294a" font-family="Inter,sans-serif" font-size="14">${ce(d.shared[j])}</text></g>`).join('')}<circle cx="280" cy="250" r="7" fill="#f8c779"/><path d="M280 260v25" stroke="#bfa4cf"/><rect x="105" y="285" width="350" height="76" rx="38" fill="#9268ac"/><text x="280" y="315" text-anchor="middle" fill="#f3eaf7" font-family="Inter,sans-serif" font-size="10" letter-spacing="2">COMPOSIÇÃO</text><text x="280" y="342" text-anchor="middle" fill="white" font-family="Inter,sans-serif" font-size="24">${ce(d.name)}</text><text x="280" y="397" text-anchor="middle" fill="#c9b6d6" font-family="Inter,sans-serif" font-size="10" letter-spacing="1.5">A BASE SE CONECTA. O CONTEXTO DÁ FORMA.</text></svg>`}
function aVertical(i){let d=A_VERTICALS[i];return `<div class="a-composition-exhibit"><div class="a-exhibit-title"><span class="label">Composição ${String(i+1).padStart(2,'0')}</span><span class="a-exhibit-status">${i<3?'Ecossistema Catalisa':'Possibilidade de composição'}</span></div>${aCompositionMap(i)}<div class="a-map-legend"><span><i></i>Capacidades reutilizáveis</span><span><i></i>Jornada própria</span></div></div><div class="a-vertical-copy"><span class="label">${d.name} / Contexto de negócio</span><h3>${d.title}</h3><p>${d.copy}</p><div class="a-specific"><small>O QUE TORNA ESTA COMPOSIÇÃO ÚNICA</small><p>${d.specific}</p></div><ol class="a-steps">${d.steps.map((x,j)=>`<li><small>0${j+1}</small>${x}</li>`).join('')}</ol>${d.note?`<p class="a-case-note">${d.note}</p>`:''}${ca(d.url||'/ecossistema/'+d.slug+'/',d.url?'Explore as capacidades':'Explore '+d.name)}</div>`}
function cArchitecture(){return `<div class="a-page"><section class="a-hero"><div class="wrap a-hero-grid"><div><span class="label">Onde nasce a eficiência / Arquitetura Catalisa</span><h1>Menos trabalho<br>repetido.<br><em>Mais produto.</em></h1><p>Reutilize capacidades. Conecte regras, dados e experiências. Dedique o próximo ciclo ao que diferencia seu produto — com uma base que já tem por onde começar.</p><a class="text-link" href="#compor">Veja a composição em ação <span>↓</span></a></div><div class="a-blueprint">${aSvg('hero')}<span class="a-caption">UMA BASE QUE SE REORGANIZA EM NOVAS POSSIBILIDADES.</span></div></div><div class="wrap a-hero-benefits"><div><span>01 / REUTILIZAR</span><p>Capacidades que atravessam produtos.</p></div><div><span>02 / COMPOR</span><p>Regras e experiências próprias para cada negócio.</p></div><div><span>03 / EVOLUIR</span><p>Mudanças organizadas por responsabilidade.</p></div></div></section>
<section class="a-path-section"><div class="wrap"><span class="label">Da intenção à nova vertical</span><h2>Começar pelo que diferencia.<br>Compor o que sustenta.</h2><div class="a-build-path">${[['Definir','Quem usa, qual problema resolve e onde uma pessoa precisa decidir.'],['Selecionar','Quais capacidades existentes atendem à jornada e quais precisam ser estendidas.'],['Compor','Conectar operações, dados e integrações com as regras do contexto.'],['Validar e evoluir','Testar contratos, permissões e a experiência completa antes de ampliar o uso.']].map(([t,d],i)=>`<article><span class="a-path-number">0${i+1}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section>
<nav class="a-chapters wrap" aria-label="Nesta página"><a href="#fundamento">01 / O fundamento</a><a href="#camadas">02 / A arquitetura</a><a href="#compor">03 / As composições</a><a href="#evolucao">04 / A evolução</a></nav>
<section class="a-section wrap" id="fundamento"><div class="a-section-head"><span class="label">Construir sobre o que já existe</span><h2>O valor não está apenas<br>em cada peça.<br><em>Está em poder usá-la de novo.</em></h2></div><div class="a-two"><div class="a-prose"><p>Todo produto tem algo único. Mas identidade, dados, cálculo, políticas e documentos aparecem em muitas jornadas financeiras — e encontram novos usos em outros setores.</p><p>A Catalisa separa essas responsabilidades em building blocks. Cada um oferece uma capacidade que pode participar de jornadas diferentes. O esforço de produto se concentra nas regras, na experiência e nas conexões que tornam aquele negócio específico.</p><p class="a-callout">Uma identidade pode abrir uma conta,<br>iniciar uma proposta ou autorizar uma operação.</p></div><div>${aSvg('reuse')}<p class="a-caption">MESMA RESPONSABILIDADE. CONTEXTOS DIFERENTES.</p></div></div></section>
<section class="a-layers" id="camadas"><div class="wrap a-two"><div><span class="label">Uma leitura da arquitetura</span><h2>Da experiência<br>ao fundamento.</h2><p>Quatro perspectivas ajudam a entender a composição. Não são uma topologia de implantação: são responsabilidades que se conectam para fazer o produto funcionar.</p>${ci('architecture.webp','Escultura explodida: partes independentes formam um conjunto','a-layer-art')}</div><div class="a-layer-stack">${[
['01','Experiência e contexto','O produto fala a língua do negócio.','Canais, interfaces, conhecimento e papéis definem como cada pessoa participa. Titular, analista de crédito e operador de backoffice acessam o mesmo fundamento a partir de papéis e experiências diferentes.','/ecossistema/','Conheça as verticais'],
['02','Composição e jornadas','A ordem das ações também é produto.','Workflows conectam capacidades, condições e pontos de revisão. A jornada define quando consultar, decidir, registrar ou encaminhar para uma pessoa.','/workflows/','Explore workflows'],
['03','Capacidades de negócio','Responsabilidades prontas para se conectar.','Dados, agenda, decisão, documentos e canais oferecem operações com fronteiras próprias. A mesma capacidade pode atender mais de uma composição.','/capacidades/','Explore building blocks'],
['04','Integrações e operação','Conectar preservando responsabilidades.','Adaptadores aproximam sistemas externos das capacidades. Identidade, permissões e registros atravessam a jornada como requisitos da operação.','/governanca/','Entenda a governança']
].map(([n,t,s,d,u,l],i)=>`<details ${i===0?'open':''}><summary><span>${n}</span><div><h3>${t}</h3><p>${s}</p></div><b aria-hidden="true">+</b></summary><div class="a-layer-detail"><p>${d}</p>${ca(u,l)}</div></details>`).join('')}</div></div></section>
<section class="a-section wrap" id="compor"><div class="a-section-head"><span class="label">A arquitetura ganha contexto</span><h2>Troque o negócio.<br><em>Reconheça a base.</em></h2><p>Banking, crédito e decisão mostram a profundidade da base. Copiloto e atendimento mostram como ela atravessa setores. Os mapas são conceituais; aplicações propostas e integrações a validar estão identificadas.</p></div><div class="a-tabs" role="tablist" aria-label="Composições por vertical">${A_VERTICALS.map((d,i)=>`<button id="a-tab-${i}" role="tab" data-a-vertical="${i}" aria-selected="${i===0}" aria-controls="a-vertical" tabindex="${i===0?0:-1}"><small>0${i+1}</small>${d.name}<span>↗</span></button>`).join('')}</div><div id="a-vertical" class="a-vertical" role="tabpanel" aria-labelledby="a-tab-0" tabindex="0">${aVertical(0)}</div></section>
<section class="a-fleet"><div class="wrap"><div class="a-fleet-heading"><div><span class="label">Laboratório de composição / uma possibilidade nova</span><h2>O veículo para.<br><em>A operação encontra<br>um próximo passo.</em></h2></div><div><span class="a-concept-tag">CENÁRIO PROPOSTO</span><h3>Continuidade para pequenas frotas</h3><p>Um serviço que conecta motorista, gestor da frota, oficina e parceiro financeiro para organizar o reparo — da primeira mensagem ao retorno do veículo.</p><p class="a-case-note">Extrapolação arquitetural. Não representa produto lançado, cliente ou integração já disponível.</p></div></div><div class="a-fleet-story"><div class="a-incident"><span class="label">01 / A ocorrência</span><blockquote>“O utilitário parou.<br>Preciso resolver o reparo<br>sem perder a semana.”</blockquote><span class="a-incident-line"></span><p>A conversa reúne identificação do veículo, relato e documentos autorizados. O gestor acompanha o caso.</p></div><div class="a-fleet-actions">${[
['02','Um especialista ganha contexto','Um copiloto reúne histórico e manuais e prepara um resumo da sessão por vídeo. O técnico valida o diagnóstico e o orçamento.','Rooms · AI Engine · File Storage'],
['03','A operação encontra uma rota','Com integrações ao ERP e à oficina, o fluxo consulta peças e horários. O gestor confirma a ordem de serviço antes da reserva.','Data Store · Calendar · Workflows'],
['04','O reparo pode encontrar uma condição','Se solicitado, cálculo, precificação e política estruturam uma proposta de financiamento. A aprovação cabe à instituição responsável; contratação exige aceite.','Calculations · Pricing · Decision · E-Signature'],
['05','O atendimento acompanha a entrega','Eventos atualizam o caso e avisam o gestor. Evidências do serviço e confirmação de entrega encerram a jornada.','Webhooks · Comunicação · Audit Trail']
].map(([n,t,d,blocks])=>`<article><span>${n}</span><div><h3>${t}</h3><p>${d}</p><small>${blocks}</small></div></article>`).join('')}</div></div><div class="a-feasibility"><div><span class="label">Reutilizar</span><p>Conversa, vídeo, IA, dados, agenda, cálculo, política e documentos como peças da composição.</p></div><div><span class="label">Construir e conectar</span><p>Modelo do caso, experiência dos participantes, ERP de peças, agenda da oficina e parceiro financeiro.</p></div><div><span class="label">Validar</span><p>Contratos de integração, acesso aos dados, qualidade do contexto e autorizações para cada ação.</p></div></div><p class="a-fleet-takeaway">O diferencial está na continuidade: <strong>o contexto acompanha a conversa, o serviço e a eventual operação financeira.</strong></p></div></section>
<section class="a-section wrap" id="evolucao"><div class="a-two"><div><span class="label">Mudar uma parte. Preservar o sentido.</span><h2>O produto não precisa<br>conhecer cada<br><em>detalhe da conexão.</em></h2><p class="a-prose">Uma integração concentra a conversa com um sistema externo. Um contrato claro permite que a jornada use a capacidade sem espalhar particularidades de um fornecedor por toda a experiência.</p><p class="a-prose">Isso cria espaço para adaptar e evoluir integrações. A troca depende de equivalência funcional, compatibilidade e testes — a fronteira organiza esse trabalho.</p></div><div>${aSvg('adapter')}<div class="a-mini-note"><strong>A esteira busca. O motor decide.</strong><p>Decision Platform reúne fontes; Decision Engine aplica a política. Separar essas funções permite usar o motor com dados próprios ou compô-lo com uma esteira.</p>${ca('/ecossistema/decision/','Explore Decision')}</div></div></div></section>
<section class="a-section wrap a-closing"><span class="label">Complexidade com estrutura</span><h2>Cada produto tem sua forma.<br><em>A base aprende a sustentar mais.</em></h2><p>Reúso não elimina o trabalho específico de cada negócio. Ele muda o ponto de partida — e permite dedicar mais atenção ao que faz o próximo produto valer a pena.</p><div>${ca('/capacidades/','Explore as capacidades')}${ca('/ecossistema/','Conheça os produtos')}${ca('/desenvolvedores/','Aprofunde a arquitetura')}</div></section></div>`}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',()=>{const tabs=[...document.querySelectorAll('[data-a-vertical]')];tabs.forEach((b,i)=>{b.addEventListener('click',()=>{tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1});const panel=document.getElementById('a-vertical');panel.innerHTML=aVertical(i);panel.setAttribute('aria-labelledby',b.id)});b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].focus();tabs[n].click()})})});
